// Des: Tests for sc-reco-vali: block pages, empty, JSON, records
// Flo: feed fixtures > assert verdicts > records with bad fields
// I/O: strings > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const vali = @import("sc-reco-vali.zig"); const fixt = @import("te-fixt-html.zig");
fn verd(ctyp: []const u8, body: []const u8) !vali.Verd { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); return vali.pageVali(aren.allocator(), ctyp, body); }
test "real page passes, block pages rejected, empty rejected" { try std.testing.expectEqual(vali.Verd.okay, try verd("text/html", fixt.shop)); try std.testing.expectEqual(vali.Verd.bloc, try verd("text/html", fixt.cfch)); try std.testing.expectEqual(vali.Verd.bloc, try verd("text/html", fixt.deny)); try std.testing.expectEqual(vali.Verd.bloc, try verd("text/html", fixt.capt)); try std.testing.expectEqual(vali.Verd.empt, try verd("text/html", fixt.emty)); try std.testing.expectEqual(vali.Verd.empt, try verd("text/html", "")); }
test "long real article that mentions captcha is not a block page" { var buff: std.ArrayList(u8) = .empty; defer buff.deinit(std.testing.allocator); try buff.appendSlice(std.testing.allocator, "<html><body><p>"); for (0..120) |_| try buff.appendSlice(std.testing.allocator, "This long article explains how a captcha works. "); try buff.appendSlice(std.testing.allocator, "</p></body></html>"); try std.testing.expectEqual(vali.Verd.okay, try verd("text/html", buff.items)); }
test "JSON: valid ok, broken bad, empty empty" { try std.testing.expectEqual(vali.Verd.okay, try verd("application/json", "{\"a\":1}")); try std.testing.expectEqual(vali.Verd.jbad, try verd("application/json", "{\"a\":")); try std.testing.expectEqual(vali.Verd.empt, try verd("application/json; charset=utf-8", " {} ")); try std.testing.expectEqual(vali.Verd.empt, try verd("application/json", "null")); try std.testing.expectEqual(vali.Verd.jbad, try verd("application/json", "<html>blocked</html>")); }
test "records: empty, null, zero and missing fields flagged" { const good = [_]vali.Fiel{ .{ .name = "name", .valu = "Blue Widget" }, .{ .name = "price", .valu = "19.90" } }; try std.testing.expect(vali.recoChek(&good, &.{ "name", "price" }) == null); const bad = [_]vali.Fiel{ .{ .name = "name", .valu = "  " }, .{ .name = "price", .valu = "0" } }; try std.testing.expectEqualStrings("name", vali.recoChek(&bad, &.{ "name", "price" }).?); const zero = [_]vali.Fiel{ .{ .name = "name", .valu = "x" }, .{ .name = "price", .valu = "0.00" } }; try std.testing.expectEqualStrings("price", vali.recoChek(&zero, &.{ "name", "price" }).?); try std.testing.expectEqualStrings("sku", vali.recoChek(&good, &.{ "name", "sku" }).?); const nul2 = [_]vali.Fiel{.{ .name = "a", .valu = "NULL" }}; try std.testing.expectEqualStrings("a", vali.recoChek(&nul2, &.{"a"}).?); }
